def chain(n, t1, t2, t3, periodic=True):
    h = np.zeros((2 * n, 2 * n))
    for j in range(n):
        h[2 * j, 2 * j + 1] -= t1
        if j + 1 < n or periodic:
            k = (j + 1) % n
            h[2 * j + 1, 2 * k] -= t2
            h[2 * j, 2 * k + 1] -= t3
    return h + h.T

