import numpy as np
def thermal(n, t1, t2, t3, beta):
    h = np.zeros((2 * n, 2 * n))
    for j in range(n):
        h[2 * j, 2 * j + 1] -= t1
        k = (j + 1) % n
        h[2 * j + 1, 2 * k] -= t2
        h[2 * j, 2 * k + 1] -= t3
    h = h + h.T
    e, v = np.linalg.eigh(h)
    return (v * (0.5 * (1.0 - np.tanh(0.5 * beta * e)))) @ v.T

